/// The fields of `OrderInputForm`, each with its label, its value as sent,
/// the attributes the input type's rules give it and its errors; a nested
/// object's in a fieldset, and a list's rows with their buttons. `form` is
/// a new form when the page passes none, and `choices` turns a text or
/// number field the app names into a select.
#[component]
pub async fn order_input_fields(
    #[default(OrderInputForm::new())] form: OrderInputForm,
    #[default] errors: FormErrors,
    #[default] choices: Choices,
) -> topcoat::Result<impl View> {
    let form_errors = errors.unshown(OrderInputForm::shows);
    Ok(view! {
        // The button Enter presses, ahead of every row button: it submits
        // the form without an `_action`.
        <button type="submit" class="ss-submit" hidden=(true)></button>
        for message in form_errors {
            <p class="form-error">(message)</p>
        }
        <fieldset class="ss-list" data-field="lines">
            <legend>"Lines"</legend>
            for message in errors.of("lines") {
                <p class="field-error">(message)</p>
            }
            #[key(i0)]
            for (i0, row0) in form.lines.iter().enumerate() {
                <fieldset class="ss-row">
                    let row = format!("lines[{i0}]");
                    let label = format!("Line {}", i0 + 1);
                    <legend>(&label)</legend>
                    <input type="hidden" name=(&row) value="">
                    for message in errors.of(&row) {
                        <p class="field-error">(message)</p>
                    }
                    <div class="field">
                        let name = format!("lines[{i0}].productId");
                        let id = format!("order-input-lines-{i0}-product-id");
                        <label for=(&id)>"Product"</label>
                        match choices.of(&name, "lines.productId") {
                            Some(options) => choice_select(id: &id, name: &name, required: true, invalid: errors.invalid(&name), options: choice_options(options, row0.product_id.as_deref())),
                            None => <input id=(&id) name=(&name) type="text" required=(true) pattern="^([0-9A-Za-z]{1,22}|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$" value=(row0.product_id.clone()) aria-invalid=(errors.invalid(&name))>,
                        }
                        for message in errors.of(&name) {
                            <p class="field-error">(message)</p>
                        }
                    </div>
                    <div class="field">
                        let name = format!("lines[{i0}].quantity");
                        let id = format!("order-input-lines-{i0}-quantity");
                        <label for=(&id)>"Quantity"</label>
                        match choices.of(&name, "lines.quantity") {
                            Some(options) => choice_select(id: &id, name: &name, required: true, invalid: errors.invalid(&name), options: choice_options(options, row0.quantity.as_deref())),
                            None => <input id=(&id) name=(&name) type="number" required=(true) step="any" min="1" max="9" value=(row0.quantity.clone()) aria-invalid=(errors.invalid(&name))>,
                        }
                        for message in errors.of(&name) {
                            <p class="field-error">(message)</p>
                        }
                    </div>
                    if form.lines.len() > 1 {
                        <button type="submit" class="ss-remove" name="_action" value=(format!("remove:{row}")) formnovalidate=(true) aria-label=(format!("Remove {label}"))>"Remove"</button>
                    }
                </fieldset>
            }
            if form.lines.len() < 3 {
                <button type="submit" class="ss-add" name="_action" value="add:lines" formnovalidate=(true)>"Add a line"</button>
            }
        </fieldset>
        <div class="field">
            <label for="order-input-gift-sku">"Gift"</label>
            match choices.of("giftSku", "giftSku") {
                Some(options) => choice_select(id: "order-input-gift-sku", name: "giftSku", required: false, invalid: errors.invalid("giftSku"), options: choice_options(options, form.gift_sku.as_deref())),
                None => <input id="order-input-gift-sku" name="giftSku" type="text" value=(form.gift_sku.clone()) aria-invalid=(errors.invalid("giftSku"))>,
            }
            for message in errors.of("giftSku") {
                <p class="field-error">(message)</p>
            }
        </div>
        <div class="field">
            <label for="order-input-note">"Note"</label>
            match choices.of("note", "note") {
                Some(options) => choice_select(id: "order-input-note", name: "note", required: false, invalid: errors.invalid("note"), options: choice_options(options, form.note.as_deref())),
                None => <input id="order-input-note" name="note" type="text" maxlength="200" value=(form.note.clone()) aria-invalid=(errors.invalid("note"))>,
            }
            for message in errors.of("note") {
                <p class="field-error">(message)</p>
            }
        </div>
    })
}

